form.button_to { display: inline-flex; margin: 0; }

/* ---------- Quiz list ---------- */

/* The tile is the <li>; its title link covers the whole card. */
.quiz-tile { position: relative; margin: 0; }
.quiz-tile:hover, .quiz-tile:focus-within { transform: translateY(-3px); }
.quiz-tile__title { margin-bottom: 12px; }
